index 0000000000000000000000000000000000000000..d6e51029b7eb3505331c7ef972cc3b7442adb270
--- /dev/null
+++ b/src/middleware/rate-limiter.ts
@@ -0,0 +1,36 @@
+import type { NextFunction, Request, Response } from "express";
+
+import { getRedis } from "../redis/client";
+
+export interface RateLimitOptions {
+  windowMs: number;
+  max: number;
+  keyPrefix?: string;
+  failOpen: boolean;
+}
+
+export function rateLimiter(options: RateLimitOptions) {
+  const windowKey = Math.floor(Date.now() / options.windowMs);
+
+  return async function rateLimitMiddleware(req: Request, res: Response, next: NextFunction) {
+    const key = `${options.keyPrefix ?? "rl"}:${req.ip}:${windowKey}`;
+    try {
+      const redis = getRedis();
+      const count = await redis.incr(key);
+      if (count === 1) {
+        await redis.pexpire(key, options.windowMs);
+      }
+      if (count > options.max) {
+        res.status(429).json({ error: "rate limit exceeded" });
+        return;
+      }
+      next();
+    } catch (err) {
+      if (options.failOpen) {
+        next();
+        return;
+      }
+      res.status(503).json({ error: "rate limiter unavailable" });
+    }
+  };
+}

